INSERT INTO commentaire_orphelin (id, empreinte, occurrence, onglet, cellule, resolu, texte, origine, source_ref) VALUES ('magies#commentaire-orphelin:57deaec8286e', '57deaec8286e', 1, 'Sommaire', 'A1', 1, 'Si jamais le coup infligé n''est pas suffisant, l''armure se recharge immédiatement après le coup, donc il faut bien mettre un seul coup unique pour la détruire.', 'magies', 'Magie Maverick V8 › Sommaire › A1 (fil 2)');
