INSERT INTO commentaire_orphelin (id, empreinte, occurrence, onglet, cellule, resolu, texte, origine, source_ref) VALUES ('magies#commentaire-orphelin:63ea5eb8b70a', '63ea5eb8b70a', 1, 'Sommaire', 'A1', 1, 'Ne se cumule pas avec "Rune Arcane"', 'magies', 'Magie Maverick V8 › Sommaire › A1 (fil 5)');
INSERT INTO commentaire_orphelin (id, empreinte, occurrence, onglet, cellule, resolu, texte, origine, source_ref) VALUES ('magies#commentaire-orphelin:83a9b0a7aff7', '83a9b0a7aff7', 1, 'Sommaire', 'A1', 1, 'Un jet de chance est nécessaire pour ne pas prendre la foudre, chaque jet au dessus de 50 se solde par un éclair dans le visage inesquivable et imparable. Chaque objet en métal porté augmente cette probabilité de 5% (l''armure est un seul objet). Réussite critique = dégâts minimum/Echec critique = Dégâts maximum. Les utilisateurs de la foudre ne prenne pas la foudre.', 'magies', 'Magie Maverick V8 › Sommaire › A1 (fil 4)');
INSERT INTO commentaire_orphelin (id, empreinte, occurrence, onglet, cellule, resolu, texte, origine, source_ref) VALUES ('magies#commentaire-orphelin:973fa00dc90a', '973fa00dc90a', 1, 'Sommaire', 'A1', 1, 'La victime ne peux rien faire dans cet état, il faut a tout prix que le lanceur rate un jet de concentration ou bien qu''il soit interrompu.', 'magies', 'Magie Maverick V8 › Sommaire › A1 (fil 17)');
